import dspy
from dspy.utils.dummies import DummyLM


reflection_lm = DummyLM([{"text": "unused"}])


def bad_metric(gold, pred):
    return 1.0


try:
    dspy.GEPA(metric=bad_metric, reflection_lm=reflection_lm, max_metric_calls=1)
except TypeError as e:
    bad_error = str(e)
else:
    raise AssertionError("Expected GEPA to reject the two-argument metric.")



def good_metric(gold, pred, trace=None, pred_name=None, pred_trace=None):
    return dspy.Prediction(score=1.0, feedback="ok")


optimizer = dspy.GEPA(metric=good_metric, reflection_lm=reflection_lm, max_metric_calls=1)
print("accepted", type(optimizer).__name__)
print(bad_error)
assert "five arguments" in bad_error
assert optimizer.metric_fn is good_metric
